session_start();if(empty($_SESSION['usuario_id'])){header('Location: ../index.php?acceso=cuenta');exit;}require_once __DIR__.'/conexion.php';$pid=(int)($_POST['producto_id']??0);$stars=(int)($_POST['calificacion']??5);$comment=trim($_POST['comentario']??'');if($pid<1||$stars<1||$stars>5||mb_strlen($comment)>1000)exit('Datos de reseña no válidos.');$q=$pdo->prepare('SELECT id FROM productos WHERE id=? AND activo=1');$q->execute([$pid]);if(!$q->fetch())exit('Producto no disponible.');$q=$pdo->prepare('SELECT id FROM pedidos WHERE usuario_id=? AND estado="entregado" AND id IN (SELECT pedido_id FROM pedido_detalles WHERE producto_id=?) ORDER BY id DESC LIMIT 1');$q->execute([$_SESSION['usuario_id'],$pid]);$order=$q->fetchColumn();if(!$order){http_response_code(403);exit('Solo puedes reseñar productos de pedidos entregados.');}try{$s=$pdo->prepare('INSERT INTO resenas(usuario_id,producto_id,pedido_id,calificacion,comentario,estado) VALUES(?,?,?,?,?,"pendiente")');$s->execute([$_SESSION['usuario_id'],$pid,$order?:null,$stars,$comment]);header('Location: ../perfil.php?resena=ok');}catch(PDOException $e){http_response_code(409);echo 'Ya enviaste una reseña para este producto o no se pudo registrar.';}
